<section class="form-section settings-component" id="seo-settings">
    <div class="section-heading"><div><p class="eyebrow">SEO</p><h2>Wartości domyślne</h2></div><p>Strony i kolekcje mogą nadpisać te wartości.</p></div>
    <div class="locale-grid"><?php foreach ($languages->languages() as $locale => $name): ?><fieldset class="form-card locale-card"><legend><?= $escape($name) ?> <code><?= $escape($locale) ?></code></legend><label>Sufiks tytułu<input name="seo_title_suffix[<?= $escape($locale) ?>]" value="<?= $escape($titleSuffix[$locale] ?? '') ?>"></label><label>Domyślny opis SEO<textarea name="seo_description[<?= $escape($locale) ?>]" maxlength="500"><?= $escape($description[$locale] ?? '') ?></textarea></label></fieldset><?php endforeach; ?></div>
    <fieldset class="form-card seo-card"><legend>Metadane wspólne</legend><label>Domyślny obraz OpenGraph<input name="seo_og_image" value="<?= $escape($string($seo['ogImage'] ?? '')) ?>" placeholder="/media/... lub https://..."></label><label>OpenGraph (JSON)<textarea class="code-editor" name="seo_open_graph" spellcheck="false"><?= $escape($json($mapping($seo['openGraph'] ?? []))) ?></textarea></label><label>Twitter/X (JSON)<textarea class="code-editor" name="seo_twitter" spellcheck="false"><?= $escape($json($mapping($seo['twitter'] ?? []))) ?></textarea></label><label>JSON-LD (JSON)<textarea class="code-editor" name="seo_json_ld" spellcheck="false"><?= $escape($json(is_array($seo['jsonLd'] ?? null) ? $seo['jsonLd'] : [])) ?></textarea></label></fieldset>
</section>
